int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int ret = 0;
    unsigned char *from_end = from + fromlen;
    unsigned char *to_ptr = to;

    while (from < from_end && ret >= 0) {
        unsigned char type = *from++;

        switch (type) {
            case PATH_COMPONENT_TYPE_SYMLINK:
                // Skip over symlinks in input, no output added
                from += 2; // Skip length bytes
                break;
            case PATH_COMPONENT_TYPE_DIR:
                if (to_ptr + 1 >= to + tolen) {
                    ret = -ENAMETOOLONG;
                    goto out;
                }
                *to_ptr++ = '/';
                break;
            case PATH_COMPONENT_TYPE_FILENAME:
                if (from >= from_end) {
                    ret = -EINVAL;
                    goto out;
                }
                {
                    int len = *from++;
                    if (to_ptr + len >= to + tolen) {
                        ret = -ENAMETOOLONG;
                        goto out;
                    }
                    for (int i = 0; i < len; i++) {
                        *to_ptr++ = *from++;
                    }
                }
                break;
            default:
                ret = -EINVAL;
                goto out;
        }
    }

    if (to_ptr >= to + tolen) {
        ret = -ENAMETOOLONG;
        goto out;
    }

    *to_ptr = '\0';
out:
    return ret;
}

int path_to_char(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i;
    unsigned char *dest = to;

    for (i = 0; i < fromlen && dest < to + tolen - 1; i++) {
        switch (from[i]) {
            case PATH_COMPONENT_TYPE_SYMLINK:
                if (dest + 3 <= to + tolen - 1) {
                    *dest++ = '[';
                    *dest++ = 's';
                    *dest++ = ']';
                } else {
                    return -ENAMETOOLONG;
                }
                break;
            case PATH_COMPONENT_TYPE_DIR:
                if (dest < to + tolen - 1) {
                    *dest++ = '/';
                }
                break;
            default:
                if (dest < to + tolen - 1) {
                    *dest++ = from[i];
                } else {
                    return -ENAMETOOLONG;
                }
                break;
        }
    }

    if (dest >= to + tolen) {
        return -ENAMETOOLONG;
    }

    *dest = '\0';
    return 0;
}

int convert_path_component(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int pos = 0;
    unsigned char *end = to + tolen - 1; // Reserve space for null terminator

    while (pos < fromlen) {
        unsigned char type = from[pos];
        unsigned char len = from[pos + 1];
        pos += 2;

        if (type == SYMLINK_TYPE) {
            if (end - to < len) {
                return -ENAMETOOLONG;
            }
            memcpy(to, from + pos, len);
            to += len;
        } else if (type == DIR_TYPE) {
            if (end - to < 1) {
                return -ENAMETOOLONG;
            }
            *to++ = '/';
        } else if (type == FILENAME_TYPE) {
            if (end - to < len) {
                return -ENAMETOOLONG;
            }
            memcpy(to, from + pos, len);
            to += len;
        } else {
            return -EINVAL;
        }

        pos += len;
    }

    if (end - to < 1) {
        return -ENAMETOOLONG;
    }
    *to = '\0';
    return 0;
}

int from_filename(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int res = 0;
    unsigned char *out = to;
    int out_len = 0;

    while (fromlen > 0 && *from) {
        if (out_len + 1 >= tolen) {
            return -ENAMETOOLONG;
        }

        *out++ = *from;
        out_len++;
        from++;
        fromlen--;
    }

    if (out_len > 0) {
        *out = '\0';
    } else {
        if (tolen > 0) {
            *out = '\0';
        }
        res = -EINVAL;
    }

    return res;
}

int convert_path_component(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int offset = 0;
    int i = 0;
    while (i < fromlen) {
        // Assuming standard encoding format for path components
        char c = from[i];

        // Skip directory indicators or special characters if needed
        if (c == '/') {
            if (offset < tolen - 1) {
                to[offset++] = c;
            } else {
                return -ENAMETOOLONG;
            }
        } else if (c == '\0') {
            // Skip null bytes
            break;
        } else {
            // Copy normal characters
            if (offset < tolen - 1) {
                to[offset++] = c;
            } else {
                return -ENAMETOOLONG;
            }
        }

        i++;
    }

    // Null-terminate the output string
    if (offset < tolen) {
        to[offset] = '\0';
    } else {
        return -ENAMETOOLONG;
    }

    return 0;
}
